import { createClient } from "@supabase/supabase-js";

/**
 * "Server-side helper" as commonly generated by AI tools: a single service-role client
 * reused for every request. The service role bypasses Row Level Security entirely.
 */
export function createServiceRoleClient() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
    { auth: { persistSession: false } },
  );
}

export async function getUserFromRequest(req: Request) {
  const auth = req.headers.get("authorization") ?? "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7) : null;
  if (!token) return null;
  const { data, error } = await createServiceRoleClient().auth.getUser(token);
  if (error || !data.user) return null;
  return data.user;
}
